<?php /* Template Name: Apply */ get_header();$oid=absint($_GET['opportunity_id']??0);$otype=sanitize_key($_GET['opportunity_type']??'');$map=['nv_job'=>'job','nv_program'=>'program','nv_scholarship'=>'scholarship','nv_internship'=>'internship'];$valid=$oid&&isset($map[$otype])&&get_post_type($oid)===$otype&&get_post_status($oid)==='publish'; ?><section class="nv-content"><div class="nv-wrap nv-apply-grid"><div><div class="nv-eyebrow"><?php esc_html_e('Start your journey','nvconsult'); ?></div><h1><?php esc_html_e('Apply with NVConsult','nvconsult'); ?></h1><?php if($valid): ?><div class="nv-card nv-selected"><span class="nv-meta"><?php esc_html_e('Selected opportunity','nvconsult'); ?></span><h3><?php echo esc_html(get_the_title($oid)); ?></h3></div><?php endif; ?><p class="nv-lead"><?php esc_html_e('Submit your basic details. Your application will be created securely and the NVConsult team can guide the next steps.','nvconsult'); ?></p></div><div class="nv-card"><form id="nv-apply-form" class="nv-form"><label><?php esc_html_e('Full name','nvconsult'); ?><input name="name" required maxlength="150" autocomplete="name"></label><label><?php esc_html_e('Email','nvconsult'); ?><input type="email" name="email" required autocomplete="email"></label><label><?php esc_html_e('Phone / WhatsApp','nvconsult'); ?><input name="phone" maxlength="50" autocomplete="tel"></label><input type="hidden" name="type" value="<?php echo esc_attr($valid?$map[$otype]:'general'); ?>"><input type="hidden" name="target_id" value="<?php echo $valid?absint($oid):0; ?>"><label class="nv-consent"><input type="checkbox" required> <span><?php esc_html_e('I confirm the information is accurate and agree that NVConsult may use it to process my enquiry/application.','nvconsult'); ?></span></label><button class="nv-btn nv-full" type="submit"><?php esc_html_e('Create application','nvconsult'); ?></button><p id="nv-apply-feedback" class="nv-feedback" aria-live="polite"></p></form></div></div></section><script>document.addEventListener('DOMContentLoaded',()=>{const f=document.getElementById('nv-apply-form'),o=document.getElementById('nv-apply-feedback');if(!f)return;f.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f).entries());o.textContent='<?php echo esc_js(__('Creating your application…','nvconsult')); ?>';try{const r=await fetch('<?php echo esc_url(rest_url('nvconsult/v1/applications')); ?>',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}),d=await r.json();if(!r.ok)throw new Error(d.message||'Request failed');f.innerHTML='<div class="nv-success"><h3><?php echo esc_js(__('Application created','nvconsult')); ?></h3><p><?php echo esc_js(__('Your reference is','nvconsult')); ?> #'+d.application_id+'.</p><p><?php echo esc_js(__('Keep the tracking token safe until your applicant account is connected.','nvconsult')); ?></p><textarea readonly>'+d.tracking_token+'</textarea><a class="nv-btn nv-full" href="<?php echo esc_url(nvconsult_theme_url('applicant-portal')); ?>"><?php echo esc_js(__('Go to Applicant Portal','nvconsult')); ?></a></div>'}catch(x){o.textContent=x.message}})});</script><?php get_footer(); ?>
